const rateConfig = [
  { frequency: 'DAILY', rate_type: 'EURX', from_currency: 'EUR' },
  { frequency: 'DAILY', rate_type: 'M', from_currency: 'EUR' },
  { frequency: 'DAILY', rate_type: 'M', from_currency: 'USD' },
  { frequency: 'MONTH_END', rate_type: 'M', from_currency: 'CAD' },
  { frequency: 'MONTH_END', rate_type: 'M', from_currency: 'HKD' },
  { frequency: 'MONTH_END', rate_type: 'M', from_currency: 'SGD' },
  { frequency: 'MONTH_END', rate_type: 'M', from_currency: 'JPY' },
];

const input = $input.first()?.json ?? {};
const forceMonthEnd = input.force_month_end === true
  || String(input.force_month_end ?? '').toLowerCase() === 'true';
const timeZone = 'Asia/Shanghai';
const now = new Date();
const dateParts = Object.fromEntries(
  new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  })
    .formatToParts(now)
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value]),
);

const year = Number(dateParts.year);
const month = Number(dateParts.month);
const day = Number(dateParts.day);
const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
const isMonthEnd = day === lastDay;
const dueRates = rateConfig.filter(
  (row) => row.frequency === 'DAILY' || isMonthEnd || forceMonthEnd,
);
const currencies = [...new Set(dueRates.map((row) => row.from_currency))];
const requestedDate = `${dateParts.year}-${dateParts.month}-${dateParts.day}`;
const validFrom = `${dateParts.year}${dateParts.month}${dateParts.day}`;

return [{
  json: {
    requested_date: requestedDate,
    valid_from: validFrom,
    timezone: timeZone,
    is_month_end: isMonthEnd,
    force_month_end: forceMonthEnd,
    due_rates: dueRates,
    currencies,
  },
}];

const plan = $('生成本次汇率计划').item.json;
const resolved = $json;

if (resolved.status !== 'success' || !Array.isArray(resolved.rates)) {
  throw new Error(`Exchange-rate service returned invalid status: ${resolved.status}`);
}

if (!/^\d{8}$/.test(plan.valid_from)) {
  throw new Error(`Invalid valid_from date: ${plan.valid_from}`);
}

const rateByCurrency = new Map(
  resolved.rates.map((rate) => [rate.from_currency, rate]),
);

const formatRate = (value) => {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) {
    throw new Error(`Invalid exchange rate: ${value}`);
  }
  return number.toFixed(8).replace(/0+$/, '').replace(/\.$/, '');
};

const rates = plan.due_rates.map((config) => {
  const resolvedRate = rateByCurrency.get(config.from_currency);
  if (!resolvedRate) {
    throw new Error(`Missing resolved rate for ${config.from_currency}`);
  }

  return {
    kurst: config.rate_type,
    fcurr: config.from_currency,
    tcurr: 'CNY',
    gdatu: plan.valid_from,
    ukurs: formatRate(resolvedRate.rate),
    ffact: String(resolvedRate.from_factor),
    tfact: String(resolvedRate.to_factor),
  };
});

return [{
  json: {
    requested_date: plan.requested_date,
    valid_from: plan.valid_from,
    sap_gdatu: plan.valid_from,
    source_date: resolved.source_date,
    provider: resolved.provider,
    source_url: resolved.source_url,
    warnings: resolved.warnings ?? [],
    sap_request: {
      operation: 'finance.exchange-rate.set.v1',
      environment: 'prd',
      confirm_write: true,
      rates,
    },
  },
}];

const response = $json;
const context = $('构建 SAP 批量请求').item.json;
const expectedCount = context.sap_request.rates.length;

if (response.status !== 'S') {
  throw new Error(`SAP exchange-rate write failed: ${response.message ?? 'unknown error'}`);
}

if (Number(response.rate_count) !== expectedCount) {
  throw new Error(`SAP rate_count mismatch: expected ${expectedCount}, received ${response.rate_count}`);
}

return [{
  json: {
    status: 'success',
    environment: response.environment,
    provider: context.provider,
    requested_date: context.requested_date,
    source_date: context.source_date,
    valid_from: context.valid_from,
    written_count: Number(response.rate_count),
    sap_function: response.function,
    sap_message: response.message,
    warnings: context.warnings,
  },
}];
